const AL = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const crypto = require('crypto');

function b58encode(buf) {
  let n = 0n;
  for (const b of buf) n = n * 256n + BigInt(b);
  let out = '';
  if (n === 0n) out = '';
  while (n > 0n) { out = AL[Number(n % 58n)] + out; n = n / 58n; }
  let z = 0; while (z < buf.length && buf[z] === 0) z++;
  return '1'.repeat(z) + (buf.length === 0 ? '' : (out === '' ? '1' : out)).replace(/^$/, '');
}
// careful: python b58encode(b'') == b'' ; b58encode(b'\0') == b'1'
function b58enc(buf) {
  let n = 0n;
  for (const b of buf) n = n * 256n + BigInt(b);
  let body = '';
  while (n > 0n) { body = AL[Number(n % 58n)] + body; n = n / 58n; }
  let z = 0; while (z < buf.length && buf[z] === 0) z++;
  return '1'.repeat(z) + body;
}
function b58dec(s) {
  // rstrip python-str whitespace done by caller
  let z = 0; while (z < s.length && s[z] === '1') z++;
  const rest = s.slice(z);
  let n = 0n;
  for (const ch of rest) {
    const i = AL.indexOf(ch);
    if (i < 0) throw new Error('Invalid character ' + JSON.stringify(ch));
    n = n * 58n + BigInt(i);
  }
  const bytes = [];
  while (n > 0n) { bytes.unshift(Number(n % 256n)); n = n / 256n; }
  return Buffer.from(Array(z).fill(0).concat(bytes));
}
function sha256(b) { return crypto.createHash('sha256').update(b).digest(); }
function encCheck(buf) {
  const d = sha256(sha256(buf)).subarray(0, 4);
  return b58enc(Buffer.concat([buf, d]));
}
function pyrepr(buf) {
  const hasS = buf.includes(0x27), hasD = buf.includes(0x22);
  const q = (hasS && !hasD) ? '"' : "'";
  let s = 'b' + q;
  for (const b of buf) {
    if (b === 0x5c) s += '\\\\';
    else if (String.fromCharCode(b) === q) s += '\\' + q;
    else if (b === 0x09) s += '\\t';
    else if (b === 0x0a) s += '\\n';
    else if (b === 0x0d) s += '\\r';
    else if (b < 0x20 || b === 0x7f || b >= 0x80) s += '\\x' + b.toString(16).padStart(2, '0');
    else s += String.fromCharCode(b);
  }
  return s + q;
}
module.exports = { b58enc, b58dec, encCheck, pyrepr, AL };
if (require.main === module) {
  const [, , cmd, ...rest] = process.argv;
  if (cmd === 'enc') console.log(pyrepr(Buffer.from(b58enc(Buffer.from(rest[0], 'utf8')))));
  else if (cmd === 'encraw') console.log(pyrepr(Buffer.from(b58enc(Buffer.from(rest[0], 'hex')))));
  else if (cmd === 'dec') console.log(pyrepr(b58dec(rest[0])));
  else if (cmd === 'dechex') console.log(b58dec(rest[0]).toString('hex'));
  else if (cmd === 'chk') console.log(pyrepr(Buffer.from(encCheck(Buffer.from(rest[0], 'hex')))));
  else if (cmd === 'findenc') console.log(b58enc(Buffer.from(rest[0], 'hex')));
  else if (cmd === 'repr') console.log(pyrepr(Buffer.from(rest[0], 'hex')));
}

